CREATE OR REPLACE FUNCTION public.sor_morth_analysis_options(p_recipe_code text, p_year text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare resolved jsonb; y public."SOR_Year"; n bigint; options jsonb;
begin
 resolved:=public.sor_resolve_recipe_year(p_recipe_code,p_year);
 if coalesce((resolved->>'requires_review')::boolean,false) then return resolved; end if;
 select count(*) into n from public."SOR_Year" where recipe_code=resolved->>'recipe_code' and year=p_year;
 if n<>1 then return resolved||jsonb_build_object('status',case when n=0 then 'selected_year_rate_missing' else 'annual_scope_review_required' end,'rate',null); end if;
 select * into y from public."SOR_Year" where recipe_code=resolved->>'recipe_code' and year=p_year;
 if y.rate->>'type' is distinct from 'morth_analysis' then return resolved||jsonb_build_object('status','not_morth_analysis_reference','rate',null); end if;
 select coalesce(jsonb_agg(o.value||jsonb_build_object('description',m.description,
  'description_detail',m.description_detail,'project_category',m.project_category,'unit',m.unit,
  'analysis_quantity',m.analysis_quantity,'rate_divisor',m.rate_divisor,'analysis',m.recipe,
  'can_auto_price',false) order by o.n),'[]'::jsonb) into options
 from jsonb_array_elements(y.rate->'options') with ordinality o(value,n)
 join public.morth m on m.code=o.value->>'morth_code';
 return resolved||jsonb_build_object('year',p_year,'year_row_code',y.year_row_code,'unit',y.unit,'status',y.rate->>'status',
  'rate',null,'cost_ready',false,'options',options,'requirements',y.rate->'requirements','reason',y.rate->>'reason',
  'review',y.metadata->'morth_link_review','to_be_printed',y.to_be_printed);
end $function$
